	return out
}

func unionHashPoliciesCount(hi, lo []*envoyroutev3.RouteAction_HashPolicy) ([]*envoyroutev3.RouteAction_HashPolicy, int) {
	if len(hi)+len(lo) == 0 {
		return nil, 0
	}
	seen := make(map[string]struct{}, len(hi)+len(lo))
	out := make([]*envoyroutev3.RouteAction_HashPolicy, 0, len(hi)+len(lo))
	for _, hp := range hi {
		key := hashPolicyKey(hp)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, hp)
	}
	fromLo := 0
	for _, hp := range lo {
		key := hashPolicyKey(hp)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, hp)
		fromLo++
	}
	return out, fromLo
}

// mergeConsistentHashIR merges the lower priority IR lo into the higher priority IR hi,
// returning a new IR and whether lo contributed to the result.
// Array fields are unioned with hi's entries first and deduplicated by key, while
// sourceIp retains hi's value even when unset. If either IR is disabled, the result
// is hi as lo cannot contribute: a disabled hi suppresses lo, and a disabled lo has
// nothing to contribute.
func mergeConsistentHashIR(hi, lo *consistentHashIR) (*consistentHashIR, bool) {
