		return hi, false
	}
	if hi == nil {
		return lo, true
	}
	if hi.disable || lo.disable {
		return hi, false
	}

	out := &consistentHashIR{
		sourceIP: hi.sourceIP,
	}
	var n, total int
	out.headers, n = unionHashPoliciesCount(hi.headers, lo.headers)
	total += n
	out.cookies, n = unionHashPoliciesCount(hi.cookies, lo.cookies)
	total += n
	out.queryParameters, n = unionHashPoliciesCount(hi.queryParameters, lo.queryParameters)
	total += n
	out.filterState, n = unionHashPoliciesCount(hi.filterState, lo.filterState)
	total += n
	return out, total > 0
}

// applyConsistentHash applies the consistent hash configuration to the Envoy route action.
func applyConsistentHash(consistentHash *consistentHashIR, action *envoyroutev3.RouteAction) {
	if consistentHash == nil || action == nil {
		return
	}
