package trafficpolicy

import (
	"testing"
	"time"

	envoyroutev3 "github.com/envoyproxy/go-control-plane/envoy/config/route/v3"
	envoy_type_matcher_v3 "github.com/envoyproxy/go-control-plane/envoy/type/matcher/v3"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/types/known/durationpb"
	"k8s.io/utils/ptr"

	"github.com/kgateway-dev/kgateway/v2/api/v1alpha1/kgateway"
	"github.com/kgateway-dev/kgateway/v2/pkg/pluginsdk/ir"
	"github.com/kgateway-dev/kgateway/v2/pkg/pluginsdk/policy"
)

func headerHP(name string, terminal bool) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{
			Header: &envoyroutev3.RouteAction_HashPolicy_Header{HeaderName: name},
		},
		Terminal: terminal,
	}
}

func cookieHP(name string) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
			Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{Name: name},
		},
	}
}

func queryHP(name string) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_QueryParameter_{
			QueryParameter: &envoyroutev3.RouteAction_HashPolicy_QueryParameter{Name: name},
		},
	}
}

func filterStateHP(key string) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_FilterState_{
			FilterState: &envoyroutev3.RouteAction_HashPolicy_FilterState{Key: key},
		},
	}
}

func assertHashPolicies(t *testing.T, expected, actual []*envoyroutev3.RouteAction_HashPolicy) {
	t.Helper()
	assert.True(t, hashPoliciesEqual(expected, actual), "expected %v, got %v", expected, actual)
}

func TestConstructConsistentHash(t *testing.T) {
	tests := []struct {
		name     string
		in       *kgateway.ConsistentHash
		expected []*envoyroutev3.RouteAction_HashPolicy
		wantErr  string
	}{
		{
			name:     "empty defaults to non-terminal source ip",
			in:       &kgateway.ConsistentHash{},
			expected: []*envoyroutev3.RouteAction_HashPolicy{sourceIPHashPolicy(false)},
		},
		{
			name:     "disable produces no hash policies",
			in:       &kgateway.ConsistentHash{Disable: ptr.To(true)},
			expected: nil,
		},
		{
			name: "canonical type order and dedup",
			in: &kgateway.ConsistentHash{
				SourceIP: &kgateway.ConsistentHashSourceIP{Terminal: ptr.To(true)},
				FilterState: []kgateway.ConsistentHashFilterState{
					{Key: "fs"}, {Key: "fs", Terminal: ptr.To(true)},
				},
				QueryParameters: []kgateway.ConsistentHashQueryParameter{
					{Name: "q"}, {Name: "q", Terminal: ptr.To(true)},
				},
				Cookies: []kgateway.ConsistentHashCookie{
					{Name: "c"}, {Name: "c", Terminal: ptr.To(true)},
				},
				Headers: []kgateway.ConsistentHashHeader{
					{HeaderName: "X-User", Terminal: ptr.To(true)},
					{HeaderName: "x-user"},
					{HeaderName: "x-other"},
				},
			},
			expected: []*envoyroutev3.RouteAction_HashPolicy{
				headerHP("X-User", true),
				headerHP("x-other", false),
				cookieHP("c"),
				queryHP("q"),
				filterStateHP("fs"),
				sourceIPHashPolicy(true),
			},
		},
		{
			name: "header regex rewrite",
			in: &kgateway.ConsistentHash{
				Headers: []kgateway.ConsistentHashHeader{{
					HeaderName:   "x-user",
					RegexRewrite: &kgateway.ConsistentHashRegexRewrite{Pattern: "^(.*)-.*$", Substitution: `\1`},
				}},
			},
			expected: []*envoyroutev3.RouteAction_HashPolicy{{
				PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{
					Header: &envoyroutev3.RouteAction_HashPolicy_Header{
						HeaderName: "x-user",
						RegexRewrite: &envoy_type_matcher_v3.RegexMatchAndSubstitute{
							Pattern:      &envoy_type_matcher_v3.RegexMatcher{Regex: "^(.*)-.*$"},
							Substitution: `\1`,
						},
					},
				},
			}},
		},
		{
			name: "cookie ttl, path and attributes",
			in: &kgateway.ConsistentHash{
				Cookies: []kgateway.ConsistentHashCookie{
					{
						Name: "a",
						TTL:  ptr.To("1h30m"),
						Path: ptr.To("/"),
						Attributes: []kgateway.ConsistentHashCookieAttribute{
							{Name: "SameSite", Value: ptr.To("Strict")},
							{Name: "Secure"},
						},
					},
					{Name: "b", TTL: ptr.To("3600")},
				},
			},
			expected: []*envoyroutev3.RouteAction_HashPolicy{
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
						Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{
							Name: "a",
							Ttl:  durationpb.New(90 * time.Minute),
							Path: "/",
							Attributes: []*envoyroutev3.RouteAction_HashPolicy_CookieAttribute{
								{Name: "SameSite", Value: "Strict"},
								{Name: "Secure"},
							},
						},
					},
				},
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
						Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{
							Name: "b",
							Ttl:  durationpb.New(time.Hour),
						},
					},
				},
			},
		},
		{
			name: "invalid cookie ttl",
			in: &kgateway.ConsistentHash{
				Cookies: []kgateway.ConsistentHashCookie{{Name: "a", TTL: ptr.To("bogus")}},
			},
			wantErr: `invalid consistentHash cookie "a" ttl`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			out := &trafficPolicySpecIr{}
			err := constructConsistentHash(kgateway.TrafficPolicySpec{ConsistentHash: tt.in}, out)
			if tt.wantErr != "" {
				require.ErrorContains(t, err, tt.wantErr)
				return
			}
			require.NoError(t, err)
			require.NotNil(t, out.consistentHash)
			require.NoError(t, out.consistentHash.Validate())
			assertHashPolicies(t, tt.expected, out.consistentHash.hashPolicies())
		})
	}
}

func TestConstructConsistentHashUnset(t *testing.T) {
	out := &trafficPolicySpecIr{}
	require.NoError(t, constructConsistentHash(kgateway.TrafficPolicySpec{}, out))
	assert.Nil(t, out.consistentHash)
}

func TestConsistentHashValidateInvalidRegex(t *testing.T) {
	out := &trafficPolicySpecIr{}
	require.NoError(t, constructConsistentHash(kgateway.TrafficPolicySpec{
		ConsistentHash: &kgateway.ConsistentHash{
			Headers: []kgateway.ConsistentHashHeader{{
				HeaderName:   "x-user",
				RegexRewrite: &kgateway.ConsistentHashRegexRewrite{Pattern: "(", Substitution: "x"},
			}},
		},
	}, out))
	assert.ErrorContains(t, out.consistentHash.Validate(), "invalid consistentHash header regexRewrite pattern")
}

func TestConsistentHashIREquals(t *testing.T) {
	a := &consistentHashIR{headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x", false)}}
	b := &consistentHashIR{headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x", false)}}
	c := &consistentHashIR{headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x", true)}}
	var nilIR *consistentHashIR

	assert.True(t, nilIR.Equals(nilIR))
	assert.False(t, nilIR.Equals(a))
	assert.False(t, a.Equals(nilIR))
	assert.True(t, a.Equals(b))
	assert.False(t, a.Equals(c))
	assert.False(t, a.Equals(&consistentHashIR{disable: true}))
	assert.False(t, a.Equals(&consistentHashIR{headers: a.headers, sourceIP: sourceIPHashPolicy(false)}))
}

func TestMergeConsistentHash(t *testing.T) {
	p1Ref := &ir.AttachedPolicyRef{Group: "gateway.kgateway.dev", Kind: "TrafficPolicy", Namespace: "default", Name: "p1"}
	p2Ref := &ir.AttachedPolicyRef{Group: "gateway.kgateway.dev", Kind: "TrafficPolicy", Namespace: "default", Name: "p2"}

	tests := []struct {
		name            string
		strategy        policy.MergeStrategy
		p1              *consistentHashIR
		p2              *consistentHashIR
		expected        []*envoyroutev3.RouteAction_HashPolicy
		expectedOrigins []string
	}{
		{
			name:     "p1 unset takes p2",
			strategy: policy.AugmentedShallowMerge,
			p1:       nil,
			p2: &consistentHashIR{
				headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-a", false)},
			},
			expected:        []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-a", false)},
			expectedOrigins: []string{p2Ref.ID()},
		},
		{
			name:     "union with higher priority first, dedup, canonical order, sourceIp from higher priority",
			strategy: policy.AugmentedShallowMerge,
			p1: &consistentHashIR{
				headers:     []*envoyroutev3.RouteAction_HashPolicy{headerHP("X-A", true)},
				filterState: []*envoyroutev3.RouteAction_HashPolicy{filterStateHP("fs")},
			},
			p2: &consistentHashIR{
				headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-a", false), headerHP("x-b", false)},
				cookies: []*envoyroutev3.RouteAction_HashPolicy{cookieHP("c")},
				sourceIP: sourceIPHashPolicy(true),
			},
			expected: []*envoyroutev3.RouteAction_HashPolicy{
				headerHP("X-A", true),
				headerHP("x-b", false),
				cookieHP("c"),
				filterStateHP("fs"),
			},
			expectedOrigins: []string{p1Ref.ID(), p2Ref.ID()},
		},
		{
			name:     "higher priority disable suppresses lower priority",
			strategy: policy.AugmentedShallowMerge,
			p1:       &consistentHashIR{disable: true},
			p2: &consistentHashIR{
				headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-a", false)},
			},
			expected:        nil,
			expectedOrigins: []string{p1Ref.ID()},
		},
		{
			name:     "lower priority disable does not affect higher priority",
			strategy: policy.AugmentedShallowMerge,
			p1: &consistentHashIR{
				queryParameters: []*envoyroutev3.RouteAction_HashPolicy{queryHP("q")},
			},
			p2:              &consistentHashIR{disable: true},
			expected:        []*envoyroutev3.RouteAction_HashPolicy{queryHP("q")},
			expectedOrigins: []string{p1Ref.ID()},
		},
		{
			name:     "overridable strategy prefers p2",
			strategy: policy.OverridableShallowMerge,
			p1: &consistentHashIR{
				headers:  []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-a", false)},
				sourceIP: sourceIPHashPolicy(false),
			},
			p2: &consistentHashIR{
				headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-b", false), headerHP("X-A", true)},
			},
			expected:        []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-b", false), headerHP("X-A", true)},
			expectedOrigins: []string{p2Ref.ID()},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			p1 := &TrafficPolicy{}
			mergeOrigins := ir.MergeOrigins{}
			if tt.p1 != nil {
				p1.spec.consistentHash = tt.p1
				mergeOrigins.SetOne("consistentHash", p1Ref, nil)
			}
			p2 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: tt.p2}}

			MergeTrafficPolicies(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: tt.strategy}, mergeOrigins, TrafficPolicyMergeOpts{})

			require.NotNil(t, p1.spec.consistentHash)
			assertHashPolicies(t, tt.expected, p1.spec.consistentHash.hashPolicies())
			assert.ElementsMatch(t, tt.expectedOrigins, mergeOrigins.Get("consistentHash"))
		})
	}
}

func TestApplyConsistentHash(t *testing.T) {
	route := &envoyroutev3.Route{
		Action: &envoyroutev3.Route_Route{Route: &envoyroutev3.RouteAction{}},
	}
	plugin := &trafficPolicyPluginGwPass{}

	plugin.handlePerRoutePolicies(trafficPolicySpecIr{consistentHash: &consistentHashIR{}}, route)
	assertHashPolicies(t, []*envoyroutev3.RouteAction_HashPolicy{sourceIPHashPolicy(false)}, route.GetRoute().GetHashPolicy())

	plugin.handlePerRoutePolicies(trafficPolicySpecIr{consistentHash: &consistentHashIR{disable: true}}, route)
	assert.Empty(t, route.GetRoute().GetHashPolicy(), "disable should clear hash policies")
}

