func TestConsistentHashIREquals(t *testing.T) {
	a := &consistentHashIR{headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x", false)}}
	b := &consistentHashIR{headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x", false)}}
	c := &consistentHashIR{headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x", true)}}
	var nilIR *consistentHashIR

	assert.True(t, nilIR.Equals(nilIR))
	assert.False(t, nilIR.Equals(a))
	assert.False(t, a.Equals(nilIR))
	assert.True(t, a.Equals(b))
	assert.False(t, a.Equals(c))
	assert.False(t, a.Equals(&consistentHashIR{disable: true}))
	assert.False(t, a.Equals(&consistentHashIR{headers: a.headers, sourceIP: sourceIPHashPolicy(false)}))
}

func TestMergeConsistentHash(t *testing.T) {
	p1Ref := &ir.AttachedPolicyRef{Group: "gateway.kgateway.dev", Kind: "TrafficPolicy", Namespace: "default", Name: "p1"}
	p2Ref := &ir.AttachedPolicyRef{Group: "gateway.kgateway.dev", Kind: "TrafficPolicy", Namespace: "default", Name: "p2"}

	tests := []struct {
		name            string
		strategy        policy.MergeStrategy
		p1              *consistentHashIR
		p2              *consistentHashIR
		expected        []*envoyroutev3.RouteAction_HashPolicy
		expectedOrigins []string
	}{
		{
			name:     "p1 unset takes p2",
			strategy: policy.AugmentedShallowMerge,
			p1:       nil,
			p2: &consistentHashIR{
				headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-a", false)},
			},
			expected:        []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-a", false)},
			expectedOrigins: []string{p2Ref.ID()},
		},
		{
			name:     "union with higher priority first, dedup, canonical order, sourceIp from higher priority",
			strategy: policy.AugmentedShallowMerge,
			p1: &consistentHashIR{
				headers:     []*envoyroutev3.RouteAction_HashPolicy{headerHP("X-A", true)},
				filterState: []*envoyroutev3.RouteAction_HashPolicy{filterStateHP("fs")},
			},
			p2: &consistentHashIR{
				headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-a", false), headerHP("x-b", false)},
				cookies: []*envoyroutev3.RouteAction_HashPolicy{cookieHP("c")},
				sourceIP: sourceIPHashPolicy(true),
			},
			expected: []*envoyroutev3.RouteAction_HashPolicy{
				headerHP("X-A", true),
				headerHP("x-b", false),
				cookieHP("c"),
				filterStateHP("fs"),
			},
			expectedOrigins: []string{p1Ref.ID(), p2Ref.ID()},
		},
		{
			name:     "higher priority disable suppresses lower priority",
			strategy: policy.AugmentedShallowMerge,
			p1:       &consistentHashIR{disable: true},
			p2: &consistentHashIR{
				headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-a", false)},
			},
			expected:        nil,
			expectedOrigins: []string{p1Ref.ID()},
		},
		{
			name:     "lower priority disable does not affect higher priority",
			strategy: policy.AugmentedShallowMerge,
			p1: &consistentHashIR{
				queryParameters: []*envoyroutev3.RouteAction_HashPolicy{queryHP("q")},
			},
			p2:              &consistentHashIR{disable: true},
			expected:        []*envoyroutev3.RouteAction_HashPolicy{queryHP("q")},
			expectedOrigins: []string{p1Ref.ID()},
		},
		{
			name:     "overridable strategy prefers p2",
			strategy: policy.OverridableShallowMerge,
			p1: &consistentHashIR{
				headers:  []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-a", false)},
				sourceIP: sourceIPHashPolicy(false),
			},
			p2: &consistentHashIR{
				headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-b", false), headerHP("X-A", true)},
			},
			expected:        []*envoyroutev3.RouteAction_HashPolicy{headerHP("x-b", false), headerHP("X-A", true)},
			expectedOrigins: []string{p2Ref.ID()},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			p1 := &TrafficPolicy{}
			mergeOrigins := ir.MergeOrigins{}
			if tt.p1 != nil {
				p1.spec.consistentHash = tt.p1
				mergeOrigins.SetOne("consistentHash", p1Ref, nil)
			}
			p2 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: tt.p2}}

			MergeTrafficPolicies(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: tt.strategy}, mergeOrigins, TrafficPolicyMergeOpts{})

			require.NotNil(t, p1.spec.consistentHash)
			assertHashPolicies(t, tt.expected, p1.spec.consistentHash.hashPolicies())
			assert.ElementsMatch(t, tt.expectedOrigins, mergeOrigins.Get("consistentHash"))
		})
	}
}

func TestApplyConsistentHash(t *testing.T) {
	route := &envoyroutev3.Route{
		Action: &envoyroutev3.Route_Route{Route: &envoyroutev3.RouteAction{}},
	}
	plugin := &trafficPolicyPluginGwPass{}

	plugin.handlePerRoutePolicies(trafficPolicySpecIr{consistentHash: &consistentHashIR{}}, route)
	assertHashPolicies(t, []*envoyroutev3.RouteAction_HashPolicy{sourceIPHashPolicy(false)}, route.GetRoute().GetHashPolicy())

	plugin.handlePerRoutePolicies(trafficPolicySpecIr{consistentHash: &consistentHashIR{disable: true}}, route)
	assert.Empty(t, route.GetRoute().GetHashPolicy(), "disable should clear hash policies")
}
